INSERT OR IGNORE INTO revisions(id,item_id,action,snapshot,created) VALUES('seed-portfolio','portfolio','Versi awal','{"id":"portfolio","kind":"portfolio","slug":"portofolio","draft":"{\"meta\":{\"title\":\"Kristanto Saputra — Pendidik & Perancang Solusi Digital\",\"description\":\"Portofolio Kristanto Saputra (Mr.K), guru di pedalaman Katingan, Kalimantan Tengah, yang merancang aplikasi sekolah, media STEM, dan sistem offline-first dari kebutuhan kelas sendiri.\"},\"brand\":{\"first\":\"Kristanto\",\"last\":\"Saputra\",\"degree\":\"S.Pd.\",\"tag\":\"PORTFOLIO\",\"role\":\"Guru & Perancang Solusi Digital\",\"cta\":\"Hubungi saya\"},\"hero\":{\"annos\":[{\"title\":\"Sistem Sekolah\",\"text\":\"Presensi QR, nilai, rapor, ujian tanpa internet....\"},{\"title\":\"Pembelajaran & STEM\",\"text\":\"Simulasi numerasi, koding blok, metode PIJAR....\"},{\"title\":\"AI & Android\",\"text\":\"Agen AI, aplikasi Kotlin, AI untuk kelas....\"}],\"nameSub\":\"Katingan – Kalimantan Tengah · Mr.K\",\"todoTitle\":\"To-do hari ini:\",\"todo\":[{\"text\":\"absen QR\",\"done\":true},{\"text\":\"uji tanpa sinyal\",\"done\":true},{\"text\":\"kopi lagi!\",\"done\":false}],\"quote\":\"“Yang penting tetap jalan walau sinyal hilang.”\",\"quoteBy\":\"— catatan di meja guru\",\"openTitle\":\"Terbuka untuk kolaborasi\",\"openSub\":\"Sistem sekolah · Pelatihan\\nAI & Koding — 2027\",\"badge\":\"TERBUKA KOLABORASI • 2026 • MR.K •\",\"scroll\":\"Gulir untuk jelajah\"},\"ticker\":{\"words\":[\"SISTEM SEKOLAH\",\"MEDIA STEM\",\"OFFLINE-FIRST\",\"AI PENDIDIKAN\",\"ANDROID\",\"KODING\"],\"phrases\":[\"tetap jalan walau sinyal hilang\",\"dibuat dari ruang kelas sungguhan\",\"status ditulis apa adanya\",\"data siswa dijaga\",\"kopi adalah bahan bakar\"],\"speed\":90},\"about\":{\"label\":\"Tentang saya\",\"hello\":\"Halo,\",\"prefix\":\"saya\",\"photo\":\"assets/foto-kristanto.jpg\",\"caption\":\"Kristanto Saputra, 2026\",\"bio\":[\"Saya guru ASN di SMP Negeri 5 Sanaman Mantikei, Katingan, Kalimantan Tengah, sekolah di daerah 3T. Saya mengajar Matematika serta Koding & Kecerdasan Artifisial, dan memimpin sekolah ini sebagai kepala sekolah pada 2020–2025.\",\"Di sini listrik dan sinyal tidak selalu ada. Karena itu saya merancang solusi dari kebutuhan kelas sendiri: aplikasi administrasi, media pembelajaran, dan sistem ujian yang tetap jalan tanpa internet.\",\"Saya membangun dengan bantuan AI dan alat modern, lalu menguji dan memperbaikinya bersama calon pengguna. Status setiap karya saya tulis apa adanya: mana yang sudah dipakai, mana yang masih prototipe.\"],\"tags\":[\"Sistem Sekolah\",\"Media STEM\",\"Offline-first\",\"AI Pendidikan\",\"Android\"],\"tools\":[],\"stats\":[{\"value\":\"5\",\"label\":\"Tahun memimpin sekolah (2020–2025)\"},{\"value\":\"25+\",\"label\":\"Proyek & rancangan digital\"},{\"value\":\"2026\",\"label\":\"ZEP Quiz Global Ambassador\"}]},\"work\":{\"label\":\"Karya pilihan · audit 2026\",\"title\":\"Proyek\",\"titleHl\":\"unggulan\",\"intro\":\"Karya yang lahir dari kebutuhan nyata. Klik untuk melihat masalah, solusi, dan teknologinya.\",\"filters\":[{\"key\":\"sekolah\",\"label\":\"Sekolah\"},{\"key\":\"belajar\",\"label\":\"Pembelajaran\"},{\"key\":\"ai\",\"label\":\"AI\"},{\"key\":\"android\",\"label\":\"Android\"},{\"key\":\"web\",\"label\":\"Web & Layanan\"}],\"projects\":[{\"title\":\"Kelasku\",\"sub\":\"Administrasi kelas digital\",\"cats\":[\"sekolah\",\"web\"],\"thumb\":\"kelasku\",\"image\":\"\",\"deco\":\"tape\",\"statusType\":\"live\",\"status\":\"\",\"platform\":\"Web\",\"problem\":\"Absensi, nilai, dan catatan siswa masih ditulis manual dan menyita waktu guru.\",\"solution\":\"Aplikasi web dengan kartu QR siswa untuk presensi, nilai, tugas, catatan perilaku, dan rekap otomatis.\",\"users\":\"Guru, wali kelas, siswa\",\"stack\":\"HTML/CSS/JS · Supabase (PostgreSQL) · Cloudflare Pages · GitHub\",\"ai\":\"\",\"note\":\"Sudah pernah dipakai di kelas. Versi terbaru masih disempurnakan.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/01-kelasku-dashboard-mobile-terbaru.jpeg\",\"alt\":\"Kelasku — Dashboard terbaru dari pengguna; menggantikan pratinjau Kelasku lama.\"}]},{\"title\":\"Lab Maya Air dan Api\",\"sub\":\"Simulasi numerasi banjir & kebakaran gambut\",\"cats\":[\"belajar\",\"android\"],\"thumb\":\"labmaya\",\"image\":\"\",\"deco\":\"pin\",\"statusType\":\"live\",\"status\":\"\",\"platform\":\"Android (APK)\",\"problem\":\"Bilangan bulat terasa abstrak, padahal banjir dan kebakaran gambut adalah keseharian siswa di Kalimantan.\",\"solution\":\"Simulasi muka air, alarm banjir, air gambut, kebakaran, dan kabut asap untuk belajar numerasi dari konteks sendiri.\",\"users\":\"Siswa SMP, guru\",\"stack\":\"Media interaktif · APK Android\",\"ai\":\"\",\"note\":\"APK sudah terpasang di HP. Cakupan fitur akhir dan cara pengemasan APK sedang didokumentasikan.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/02-lab-maya-beranda-mobile-terbaru.jpeg\",\"alt\":\"Lab Maya Air dan Api — Beranda terbaru dari pengguna; menggantikan screenshot beranda lama.\"},{\"src\":\"assets/projects/02-lab-maya-ikon.png\",\"alt\":\"Lab Maya Air dan Api — Ikon aplikasi.\"},{\"src\":\"assets/projects/02-lab-maya-pilihan-aktivitas.jpeg\",\"alt\":\"Lab Maya Air dan Api — Menu Bilangan, Aljabar, serta Persamaan dan Pertidaksamaan dari pengguna.\"}]},{\"image\":\"\",\"link\":\"\",\"ai\":\"Model AI lokal di laptop, tanpa internet\",\"title\":\"ThinkLab\",\"sub\":\"AI pembelajaran offline di jaringan lokal\",\"cats\":[\"ai\",\"belajar\"],\"thumb\":\"thinklab\",\"deco\":\"pin\",\"statusType\":\"live\",\"status\":\"\",\"platform\":\"Server laptop Windows + browser HP (LAN)\",\"problem\":\"Siswa di pedalaman juga berhak belajar dengan AI, walau sekolah tanpa internet.\",\"solution\":\"Tutor AI yang berjalan di laptop sekolah dan diakses siswa lewat Wi-Fi lokal. Ada avatar 3D, mode ringan untuk HP, login kartu QR, dan dashboard guru.\",\"users\":\"Siswa, guru, admin sekolah\",\"stack\":\"Installer Windows · jaringan Wi-Fi lokal · web 3D client-side\",\"note\":\"Dimulai dari PRD, kini versi 0.4 sudah berjalan. Berikutnya: versi untuk sekolah yang belum punya kartu QR.\",\"images\":[{\"src\":\"assets/projects/03-thinklab-ikon.png\",\"alt\":\"ThinkLab — Ikon dari build aplikasi. Resolusi asli 192 piksel; jangan diperbesar untuk hero.\"}]},{\"title\":\"LEWU CBT\",\"sub\":\"Ujian digital tanpa internet\",\"cats\":[\"sekolah\",\"belajar\"],\"thumb\":\"lewu\",\"image\":\"\",\"deco\":\"tape\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Web lokal (LAN) + laptop Windows\",\"problem\":\"Ujian online gagal begitu sinyal putus.\",\"solution\":\"Laptop guru jadi server, siswa ujian lewat browser di Wi-Fi lokal. Login pakai QR Kelasku, soal PG/isian/esai, monitoring, ekspor, dan backup.\",\"users\":\"Guru/pengawas, siswa SMP\",\"stack\":\"Node.js · Express · SQLite · router Wi-Fi\",\"ai\":\"\",\"note\":\"Login QR sudah berhasil. Uji serentak satu kelas penuh belum tuntas.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/04-lewu-ruang-siswa.png\",\"alt\":\"LEWU CBT — Screenshot halaman siswa utuh.\"},{\"src\":\"assets/projects/04-lewu-maskot.png\",\"alt\":\"LEWU CBT — Maskot dari dokumentasi proyek.\"}]},{\"image\":\"\",\"link\":\"\",\"ai\":\"SIMFONI Intelligence: menganalisis perkembangan siswa, efektivitas program, dan ketercapaian visi-misi, lalu memberi rekomendasi berbasis data\",\"title\":\"SIMFONI\",\"sub\":\"Manajemen sekolah terintegrasi berbasis AI\",\"cats\":[\"sekolah\",\"ai\"],\"thumb\":\"simfoni\",\"deco\":\"tape\",\"statusType\":\"concept\",\"status\":\"\",\"platform\":\"Web + AI\",\"problem\":\"Data sekolah tersebar di banyak tempat, sehingga sulit melihat perkembangan siswa dan ketercapaian visi-misi secara utuh.\",\"solution\":\"Satu platform untuk administrasi, data siswa, absensi QR, pembelajaran, penilaian, jurnal harian, pembinaan karakter, literasi-numerasi, ekstrakurikuler, program sekolah, dan komunikasi dengan orang tua.\",\"users\":\"Kepala sekolah, guru, wali kelas, siswa, orang tua, tenaga kependidikan\",\"stack\":\"Web · arsitektur sedang disusun\",\"note\":\"Sistem Informasi Manajemen dan Fungsi Operasional Pendidikan Terintegrasi. Dirancang untuk SMP Negeri 7 Katingan Hilir; aplikasi mandiri, terpisah dari Kelasku.\"},{\"image\":\"\",\"link\":\"\",\"ai\":\"Gemini API\",\"title\":\"PenaPintar AI\",\"sub\":\"Generator soal ujian berbasis AI\",\"cats\":[\"ai\"],\"thumb\":\"pena\",\"deco\":\"tape\",\"statusType\":\"dev\",\"status\":\"\",\"platform\":\"Web app\",\"problem\":\"Menyusun butir soal itu lama, sementara pekerjaan guru banyak.\",\"solution\":\"Membantu guru menghasilkan soal ujian dengan bantuan AI generatif, sehingga waktu menyusun soal jadi lebih singkat.\",\"users\":\"Guru\",\"stack\":\"Python · Streamlit\",\"note\":\"Tampilan masih terus diperbarui.\"},{\"title\":\"BlockKode\",\"sub\":\"Koding blok + kuis tarik tambang\",\"cats\":[\"belajar\",\"web\"],\"thumb\":\"blockkode\",\"image\":\"\",\"deco\":\"tape\",\"statusType\":\"dev\",\"status\":\"\",\"platform\":\"Web (layar sentuh/IFP)\",\"problem\":\"Siswa pemula butuh cara yang ramah untuk memahami logika koding.\",\"solution\":\"Playground koding visual berbasis blok, ditambah kuis tarik tambang dua tim untuk dimainkan di depan kelas.\",\"users\":\"Siswa pemula\",\"stack\":\"HTML · CSS · JavaScript\",\"ai\":\"\",\"note\":\"Sudah pernah dibuat. Pengujian dan publikasinya masih dicek.\",\"link\":\"\"},{\"title\":\"MyStep\",\"sub\":\"Aplikasi tujuan & kebiasaan\",\"cats\":[\"android\"],\"thumb\":\"mystep\",\"image\":\"\",\"deco\":\"pin\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Android native\",\"problem\":\"Butuh satu tempat sederhana untuk tujuan, kebiasaan, dan tugas harian.\",\"solution\":\"Aplikasi Android untuk mengatur tujuan, kebiasaan, rutinitas, tugas, lalu melihat progresnya.\",\"users\":\"Pengguna pribadi\",\"stack\":\"Kotlin · Jetpack Compose · Android Studio · Gradle\",\"ai\":\"\",\"note\":\"Build berhasil dijalankan di emulator Android. Uji di HP asli menyusul; belum ada di Play Store.\",\"link\":\"\"},{\"title\":\"Q-Sat Edu\",\"sub\":\"Kantor virtual 3D dengan 10 agen AI\",\"cats\":[\"ai\"],\"thumb\":\"qsat\",\"image\":\"\",\"deco\":\"tape\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Web 3D lokal + backend Windows\",\"problem\":\"Mengelola banyak proyek sendirian butuh “tim” yang bisa diajak berbagi tugas.\",\"solution\":\"Ruang kerja 3D tempat 10 agen AI virtual membantu koordinasi, rapat, dan pemantauan proyek, tersambung ke bot Telegram.\",\"users\":\"Pengelola proyek\",\"stack\":\"Three.js · backend lokal · Telegram Bot API · Cloudflare Workers\",\"ai\":\"Router AI (Gemini, Groq, NVIDIA) + model Qwen lokal, diintegrasikan bertahap\",\"note\":\"Ini agen virtual, bukan pegawai manusia. Tidak semua jalur AI aktif bersamaan.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/09-qsat-kantor-3d.png\",\"alt\":\"Q-Sat Edu — Screenshot kantor 3D versi tersimpan.\"},{\"src\":\"assets/projects/09-qsat-logo.png\",\"alt\":\"Q-Sat Edu — Logo dari sumber proyek.\"}]},{\"title\":\"PIJAR\",\"sub\":\"Debugging Matematis — metode 5 langkah\",\"cats\":[\"belajar\"],\"thumb\":\"pijar\",\"image\":\"\",\"deco\":\"pin\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Metode + modul\",\"problem\":\"Penalaran dan numerasi butuh kebiasaan menguji lalu memperbaiki, bukan sekadar menghafal rumus.\",\"solution\":\"Lima langkah: Pahami Masalah → Identifikasi & Prediksi → Jalankan & Uji → Analisis & Perbaiki → Refleksi & Replikasi. Jawaban salah diperlakukan seperti bug yang bisa diperbaiki.\",\"users\":\"Guru dan siswa SMP\",\"stack\":\"Desain pembelajaran · modul · Lab Maya\",\"ai\":\"\",\"note\":\"PIJAR adalah metode, bukan aplikasi. Bukti dampaknya sedang dikumpulkan.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/10-pijar-penerapan-lab.png\",\"alt\":\"PIJAR — Penerapan PIJAR dalam Lab Maya; bukan aplikasi PIJAR terpisah.\"},{\"src\":\"assets/projects/10-pijar-lima-tahap-mobile.png\",\"alt\":\"PIJAR — Screenshot penerapan lima tahap PIJAR.\"}]},{\"image\":\"\",\"link\":\"\",\"ai\":\"\",\"title\":\"Step by Steph Tour\",\"sub\":\"Website wisata Lombok dwibahasa\",\"cats\":[\"web\"],\"thumb\":\"steph\",\"deco\":\"pin\",\"statusType\":\"dev\",\"status\":\"\",\"platform\":\"Website\",\"problem\":\"Pengelola tur butuh website yang meyakinkan wisatawan lokal dan mancanegara.\",\"solution\":\"Informasi destinasi, paket tur, galeri, dan kontak/pemesanan dalam bahasa Indonesia dan Inggris.\",\"users\":\"Wisatawan, pengelola tur\",\"stack\":\"WordPress · Elementor\",\"note\":\"Proyek berbayar untuk klien.\"},{\"title\":\"Web SMPN 7 Katingan Hilir\",\"sub\":\"Website profil sekolah\",\"cats\":[\"web\",\"sekolah\"],\"thumb\":\"sekolah\",\"image\":\"\",\"deco\":\"pin\",\"statusType\":\"dev\",\"status\":\"\",\"platform\":\"Website\",\"problem\":\"Sekolah butuh wajah resmi di internet untuk profil, berita, galeri, dan pengumuman.\",\"solution\":\"Website profil sekolah yang ringan dan mudah diperbarui.\",\"users\":\"Masyarakat, siswa, orang tua, sekolah\",\"stack\":\"HTML/CSS/JS · rencana domain .sch.id\",\"ai\":\"\",\"note\":\"Masih dikembangkan; belum tayang resmi.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/12-smpn7-program.png\",\"alt\":\"Program SMP Negeri 7 Katingan Hilir\"},{\"src\":\"assets/projects/12-smpn7-hero.png\",\"alt\":\"Beranda SMP Negeri 7 Katingan Hilir\"}]},{\"title\":\"SIAP Kelurahan\",\"sub\":\"Antrean & panduan layanan warga\",\"cats\":[\"web\"],\"thumb\":\"layanan\",\"image\":\"\",\"deco\":\"tape\",\"statusType\":\"concept\",\"status\":\"\",\"platform\":\"Web\",\"problem\":\"Warga perlu tahu syarat layanan dan kepastian antrean sebelum datang ke kantor kelurahan.\",\"solution\":\"Meja depan digital: pilih jenis layanan → ambil nomor antrean → dipanggil petugas → laporan untuk lurah.\",\"users\":\"Warga, petugas, lurah\",\"stack\":\"Rencana: HTML/CSS/JS · Cloudflare Pages · Supabase\",\"ai\":\"\",\"note\":\"Masih berupa project brief dan rancangan rinci, belum menjadi layanan resmi.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/13-siap-kelurahan-beranda-mobile.jpeg\",\"alt\":\"SIAP Kelurahan — Beranda pelayanan terbaru dari pengguna.\"},{\"src\":\"assets/projects/13-siap-kelurahan-login-mobile.jpeg\",\"alt\":\"SIAP Kelurahan — Tampilan login terbaru dari pengguna.\"},{\"src\":\"assets/projects/13-siap-kelurahan-logo.png\",\"alt\":\"SIAP Kelurahan — Logo dari sumber proyek.\"}]},{\"title\":\"Cepat Tepat Pangkat\",\"sub\":\"Kuis kelompok bilangan berpangkat\",\"cats\":[\"belajar\",\"web\"],\"thumb\":\"ide\",\"image\":\"assets/projects/pangkat.png\",\"deco\":\"pin\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Website\",\"problem\":\"Latihan bilangan berpangkat memerlukan media kuis kelompok yang interaktif.\",\"solution\":\"Permainan kuis bilangan berpangkat dengan layar kelompok.\",\"users\":\"Siswa dan guru matematika\",\"stack\":\"HTML / CSS / JavaScript\",\"ai\":\"\",\"note\":\"Tampilan diambil dari sumber proyek lokal. Status publikasi belum diverifikasi.\",\"link\":\"\"},{\"title\":\"Math Strike Force\",\"sub\":\"Permainan matematika interaktif\",\"cats\":[\"belajar\",\"web\"],\"thumb\":\"ide\",\"image\":\"assets/projects/math-strike.png\",\"deco\":\"pin\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Website\",\"problem\":\"Latihan operasi hitung membutuhkan variasi aktivitas.\",\"solution\":\"Permainan matematika bertema robot dengan misi penjumlahan.\",\"users\":\"Siswa dan guru matematika\",\"stack\":\"HTML / CSS / JavaScript\",\"ai\":\"\",\"note\":\"Tampilan diambil dari sumber proyek lokal. Status publikasi belum diverifikasi.\",\"link\":\"\"},{\"title\":\"SMP Negeri 5 Sanaman Mantikei\",\"sub\":\"Website profil sekolah\",\"cats\":[\"sekolah\",\"web\"],\"thumb\":\"ide\",\"image\":\"assets/projects/smpn5.png\",\"deco\":\"pin\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Website\",\"problem\":\"Informasi dan dokumentasi sekolah perlu disajikan dalam satu website.\",\"solution\":\"Website profil sekolah dengan halaman profil, akademik, galeri, berita, dan kontak.\",\"users\":\"Warga sekolah dan masyarakat\",\"stack\":\"HTML / CSS / JavaScript\",\"ai\":\"\",\"note\":\"Tampilan diambil dari sumber proyek lokal. Status publikasi belum diverifikasi.\",\"link\":\"\"}],\"moreLabel\":\"Ikuti prosesnya di Instagram\",\"moreLink\":\"https://instagram.com/kelasmrk\",\"initial\":9,\"moreAll\":\"Tampilkan semua karya\"},\"expertise\":{\"title\":\"Keahlian\",\"intro\":\"Tiga hal yang saya kerjakan dan praktikkan langsung di sekolah, bukan sekadar teori.\",\"cards\":[{\"icon\":\"school\",\"title\":\"Sistem Sekolah\",\"desc\":\"Administrasi rapi, data siswa terjaga, dan bisa dirawat sendiri oleh sekolah.\",\"items\":[\"Presensi QR, nilai, rapor\",\"Ujian offline lewat Wi-Fi lokal\",\"Website profil sekolah\"],\"link\":\"Lihat proyek →\",\"go\":\"sekolah\"},{\"icon\":\"game\",\"title\":\"Media Pembelajaran & STEM\",\"desc\":\"Belajar dari konteks sendiri, tetap jalan di HP, IFP, atau tanpa internet.\",\"items\":[\"Simulasi numerasi berbasis kearifan lokal\",\"Koding blok untuk pemula\",\"Metode PIJAR untuk penalaran\"],\"link\":\"Lihat proyek →\",\"go\":\"belajar\"},{\"icon\":\"talk\",\"title\":\"Narasumber & Pelatihan\",\"desc\":\"Berbagi dari pengalaman nyata membangun di sekolah 3T.\",\"items\":[\"AI untuk guru, dipakai dengan jujur & aman\",\"Koding & KA di SMP\",\"Membangun aplikasi sekolah sendiri\"],\"link\":\"Undang saya →\",\"go\":\"contact\"}]},\"stack\":{\"label\":\"Teknologi & AI\",\"titleHl\":\"Alat\",\"title\":\"yang dipakai\",\"intro\":\"\",\"groups\":[{\"title\":\"Bahasa pemrograman\",\"note\":\"\",\"items\":[\"JavaScript\",\"TypeScript\",\"Python\",\"Kotlin\",\"Java\",\"SQL\",\"HTML\",\"CSS\",\"JSON\"]},{\"title\":\"Backend & framework\",\"note\":\"\",\"items\":[\"Node.js\",\"Express.js\",\"Flask\",\"Three.js\",\"API REST\",\"Local Server\"]},{\"title\":\"Python & aplikasi desktop\",\"note\":\"\",\"items\":[\"Tkinter\",\"Pandas\",\"PySide6\",\"PyInstaller\",\"Windows\",\"PowerShell\"]},{\"title\":\"Android & mobile\",\"note\":\"\",\"items\":[\"Jetpack Compose\",\"Gradle\",\"Android Studio\",\"Android SDK\",\"Android Emulator\",\"Android WebView\",\"Capacitor\",\"Cordova\",\"TWA\",\"PWA\",\"APK\"]},{\"title\":\"Database & cloud\",\"note\":\"\",\"items\":[\"Supabase\",\"PostgreSQL\",\"SQLite\",\"Firebase\",\"Firestore\",\"Firebase Authentication\",\"Google Cloud Run\",\"Google Cloud Secret Manager\",\"BigQuery MCP Server\"]},{\"title\":\"Hosting & versi kode\",\"note\":\"\",\"items\":[\"GitHub\",\"Git\",\"GitHub Actions\",\"Cloudflare Pages\",\"Cloudflare Workers\",\"WordPress\",\"Elementor\"]},{\"title\":\"AI & model\",\"note\":\"\",\"items\":[\"ChatGPT\",\"ChatGPT Work\",\"OpenAI API\",\"Google Gemini\",\"Gemini API\",\"Google AI Studio\",\"Gemini Canvas\",\"Groq API\",\"NVIDIA AI API\",\"Qwen\",\"Ollama\"]},{\"title\":\"Agen AI & otomasi\",\"note\":\"\",\"items\":[\"LangChain\",\"RAG\",\"Google ADK\",\"AI Agents\",\"Multi-Agent System\",\"Prompt Engineering\",\"Automation\"]},{\"title\":\"Suara & bot\",\"note\":\"\",\"items\":[\"Whisper\",\"Vosk\",\"Piper TTS\",\"Telegram Bot API\",\"WhatsApp Business Platform\"]},{\"title\":\"Sekolah offline\",\"note\":\"\",\"items\":[\"LAN\",\"Wi-Fi Router\",\"Offline-First\",\"QR Code\",\"Tailscale\"]},{\"title\":\"Desain & dokumen\",\"note\":\"\",\"items\":[\"UI/UX Design\",\"Wireframe\",\"Prototyping\",\"Canva\",\"Canva AI Code\",\"Argon\",\"Mermaid\",\"Word\",\"CSV\",\"Excel\",\"PDF\"]},{\"title\":\"Cara kerja\",\"note\":\"\",\"items\":[\"Debugging\",\"Testing\",\"Deployment\",\"Browser Developer Tools\"]}]},\"process\":{\"label\":\"Cara kerja\",\"titleHl\":\"6 langkah\",\"title\":\"dari masalah ke solusi\",\"steps\":[{\"title\":\"Masalah\",\"sub\":\"siapa kesulitan apa?\",\"text\":\"Mulai dari kelas: siapa yang kesulitan, perangkat apa yang ada, sinyalnya bagaimana.\"},{\"title\":\"Ide\",\"sub\":\"sederhana, murah, aman\",\"text\":\"Pilih solusi paling sederhana yang benar-benar bisa dipakai. Fitur canggih menunggu.\"},{\"title\":\"Sketsa\",\"sub\":\"alur & tampilan\",\"text\":\"Alur pengguna, wireframe, dan rancangan data, termasuk siapa boleh melihat data siswa.\"},{\"title\":\"Bangun\",\"sub\":\"kode & build\",\"text\":\"Membangun fitur inti dengan alat yang cocok, dibantu AI, kode tersimpan rapi di GitHub.\"},{\"title\":\"Uji\",\"sub\":\"di perangkat asli\",\"text\":\"Dites di HP dan laptop sungguhan, juga dengan internet benar-benar mati. Hasilnya dicatat apa adanya.\"},{\"title\":\"Serahkan\",\"sub\":\"panduan & pendampingan\",\"text\":\"Demo, panduan, dan cadangan data supaya pengguna bisa merawatnya sendiri.\"}],\"workedGroups\":[{\"label\":\"Sekolah, instansi & klien\",\"items\":[\"SMPN 5 Sanaman Mantikei\",\"SMPN 7 Katingan Hilir\",\"SD Negeri Tumbang Kawei\",\"Kelurahan Kasongan Lama\",\"Klinik Lapas Kelas II Palangka Raya\",\"Rumah Sehat Pendarawah\",\"Step by Steph Tour\",\"Asian Trail\"]},{\"label\":\"Program, pelatihan & komunitas\",\"items\":[\"ZEP Quiz · Global Ambassador 2026\",\"Gemini for Educators\",\"Dicoding\",\"DBS Foundation\",\"Baparekraf\",\"Maju Bareng AI\",\"Hacktiv8 Indonesia\",\"Komunitas Dev Indonesia\",\"Tegal.Dev\"]}]},\"contact\":{\"label\":\"Kontak\",\"title\":\"Yuk kerja\\nsama\",\"lead\":\"Mau membangun sistem untuk sekolah, mengundang narasumber, atau ngobrol soal AI di kelas? Kirim pesan saja.\",\"email\":\"kristantosaputra2@gmail.com\",\"socials\":{\"instagram\":\"https://instagram.com/kelasmrk\",\"tiktok\":\"\",\"youtube\":\"\",\"whatsapp\":\"\",\"facebook\":\"\",\"linkedin\":\"\",\"website\":\"\"},\"formTitle\":\"Kirim catatan singkat\",\"purposes\":[\"Undangan narasumber\",\"Sistem/aplikasi sekolah\",\"Website sekolah\",\"Media pembelajaran\",\"Lainnya\"]},\"footer\":{\"copy\":\"Kristanto Saputra · Kelas Mr.K. Dibuat dari pedalaman Kalimantan Tengah.\",\"base\":\"Mendidik dari pedalaman, membangun untuk Indonesia.\"},\"support\":{\"enabled\":false,\"mode\":\"link\",\"title\":\"Traktir Kopi\",\"message\":\"Jika catatan dan karya ini bermanfaat, kamu bisa mendukung pengembangannya dengan traktir kopi. Dukungan sepenuhnya sukarela.\",\"buttonLabel\":\"Traktir Kopi ☕\",\"url\":\"\"}}","published":"{\"meta\":{\"title\":\"Kristanto Saputra — Pendidik & Perancang Solusi Digital\",\"description\":\"Portofolio Kristanto Saputra (Mr.K), guru di pedalaman Katingan, Kalimantan Tengah, yang merancang aplikasi sekolah, media STEM, dan sistem offline-first dari kebutuhan kelas sendiri.\"},\"brand\":{\"first\":\"Kristanto\",\"last\":\"Saputra\",\"degree\":\"S.Pd.\",\"tag\":\"PORTFOLIO\",\"role\":\"Guru & Perancang Solusi Digital\",\"cta\":\"Hubungi saya\"},\"hero\":{\"annos\":[{\"title\":\"Sistem Sekolah\",\"text\":\"Presensi QR, nilai, rapor, ujian tanpa internet....\"},{\"title\":\"Pembelajaran & STEM\",\"text\":\"Simulasi numerasi, koding blok, metode PIJAR....\"},{\"title\":\"AI & Android\",\"text\":\"Agen AI, aplikasi Kotlin, AI untuk kelas....\"}],\"nameSub\":\"Katingan – Kalimantan Tengah · Mr.K\",\"todoTitle\":\"To-do hari ini:\",\"todo\":[{\"text\":\"absen QR\",\"done\":true},{\"text\":\"uji tanpa sinyal\",\"done\":true},{\"text\":\"kopi lagi!\",\"done\":false}],\"quote\":\"“Yang penting tetap jalan walau sinyal hilang.”\",\"quoteBy\":\"— catatan di meja guru\",\"openTitle\":\"Terbuka untuk kolaborasi\",\"openSub\":\"Sistem sekolah · Pelatihan\\nAI & Koding — 2027\",\"badge\":\"TERBUKA KOLABORASI • 2026 • MR.K •\",\"scroll\":\"Gulir untuk jelajah\"},\"ticker\":{\"words\":[\"SISTEM SEKOLAH\",\"MEDIA STEM\",\"OFFLINE-FIRST\",\"AI PENDIDIKAN\",\"ANDROID\",\"KODING\"],\"phrases\":[\"tetap jalan walau sinyal hilang\",\"dibuat dari ruang kelas sungguhan\",\"status ditulis apa adanya\",\"data siswa dijaga\",\"kopi adalah bahan bakar\"],\"speed\":90},\"about\":{\"label\":\"Tentang saya\",\"hello\":\"Halo,\",\"prefix\":\"saya\",\"photo\":\"assets/foto-kristanto.jpg\",\"caption\":\"Kristanto Saputra, 2026\",\"bio\":[\"Saya guru ASN di SMP Negeri 5 Sanaman Mantikei, Katingan, Kalimantan Tengah, sekolah di daerah 3T. Saya mengajar Matematika serta Koding & Kecerdasan Artifisial, dan memimpin sekolah ini sebagai kepala sekolah pada 2020–2025.\",\"Di sini listrik dan sinyal tidak selalu ada. Karena itu saya merancang solusi dari kebutuhan kelas sendiri: aplikasi administrasi, media pembelajaran, dan sistem ujian yang tetap jalan tanpa internet.\",\"Saya membangun dengan bantuan AI dan alat modern, lalu menguji dan memperbaikinya bersama calon pengguna. Status setiap karya saya tulis apa adanya: mana yang sudah dipakai, mana yang masih prototipe.\"],\"tags\":[\"Sistem Sekolah\",\"Media STEM\",\"Offline-first\",\"AI Pendidikan\",\"Android\"],\"tools\":[],\"stats\":[{\"value\":\"5\",\"label\":\"Tahun memimpin sekolah (2020–2025)\"},{\"value\":\"25+\",\"label\":\"Proyek & rancangan digital\"},{\"value\":\"2026\",\"label\":\"ZEP Quiz Global Ambassador\"}]},\"work\":{\"label\":\"Karya pilihan · audit 2026\",\"title\":\"Proyek\",\"titleHl\":\"unggulan\",\"intro\":\"Karya yang lahir dari kebutuhan nyata. Klik untuk melihat masalah, solusi, dan teknologinya.\",\"filters\":[{\"key\":\"sekolah\",\"label\":\"Sekolah\"},{\"key\":\"belajar\",\"label\":\"Pembelajaran\"},{\"key\":\"ai\",\"label\":\"AI\"},{\"key\":\"android\",\"label\":\"Android\"},{\"key\":\"web\",\"label\":\"Web & Layanan\"}],\"projects\":[{\"title\":\"Kelasku\",\"sub\":\"Administrasi kelas digital\",\"cats\":[\"sekolah\",\"web\"],\"thumb\":\"kelasku\",\"image\":\"\",\"deco\":\"tape\",\"statusType\":\"live\",\"status\":\"\",\"platform\":\"Web\",\"problem\":\"Absensi, nilai, dan catatan siswa masih ditulis manual dan menyita waktu guru.\",\"solution\":\"Aplikasi web dengan kartu QR siswa untuk presensi, nilai, tugas, catatan perilaku, dan rekap otomatis.\",\"users\":\"Guru, wali kelas, siswa\",\"stack\":\"HTML/CSS/JS · Supabase (PostgreSQL) · Cloudflare Pages · GitHub\",\"ai\":\"\",\"note\":\"Sudah pernah dipakai di kelas. Versi terbaru masih disempurnakan.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/01-kelasku-dashboard-mobile-terbaru.jpeg\",\"alt\":\"Kelasku — Dashboard terbaru dari pengguna; menggantikan pratinjau Kelasku lama.\"}]},{\"title\":\"Lab Maya Air dan Api\",\"sub\":\"Simulasi numerasi banjir & kebakaran gambut\",\"cats\":[\"belajar\",\"android\"],\"thumb\":\"labmaya\",\"image\":\"\",\"deco\":\"pin\",\"statusType\":\"live\",\"status\":\"\",\"platform\":\"Android (APK)\",\"problem\":\"Bilangan bulat terasa abstrak, padahal banjir dan kebakaran gambut adalah keseharian siswa di Kalimantan.\",\"solution\":\"Simulasi muka air, alarm banjir, air gambut, kebakaran, dan kabut asap untuk belajar numerasi dari konteks sendiri.\",\"users\":\"Siswa SMP, guru\",\"stack\":\"Media interaktif · APK Android\",\"ai\":\"\",\"note\":\"APK sudah terpasang di HP. Cakupan fitur akhir dan cara pengemasan APK sedang didokumentasikan.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/02-lab-maya-beranda-mobile-terbaru.jpeg\",\"alt\":\"Lab Maya Air dan Api — Beranda terbaru dari pengguna; menggantikan screenshot beranda lama.\"},{\"src\":\"assets/projects/02-lab-maya-ikon.png\",\"alt\":\"Lab Maya Air dan Api — Ikon aplikasi.\"},{\"src\":\"assets/projects/02-lab-maya-pilihan-aktivitas.jpeg\",\"alt\":\"Lab Maya Air dan Api — Menu Bilangan, Aljabar, serta Persamaan dan Pertidaksamaan dari pengguna.\"}]},{\"image\":\"\",\"link\":\"\",\"ai\":\"Model AI lokal di laptop, tanpa internet\",\"title\":\"ThinkLab\",\"sub\":\"AI pembelajaran offline di jaringan lokal\",\"cats\":[\"ai\",\"belajar\"],\"thumb\":\"thinklab\",\"deco\":\"pin\",\"statusType\":\"live\",\"status\":\"\",\"platform\":\"Server laptop Windows + browser HP (LAN)\",\"problem\":\"Siswa di pedalaman juga berhak belajar dengan AI, walau sekolah tanpa internet.\",\"solution\":\"Tutor AI yang berjalan di laptop sekolah dan diakses siswa lewat Wi-Fi lokal. Ada avatar 3D, mode ringan untuk HP, login kartu QR, dan dashboard guru.\",\"users\":\"Siswa, guru, admin sekolah\",\"stack\":\"Installer Windows · jaringan Wi-Fi lokal · web 3D client-side\",\"note\":\"Dimulai dari PRD, kini versi 0.4 sudah berjalan. Berikutnya: versi untuk sekolah yang belum punya kartu QR.\",\"images\":[{\"src\":\"assets/projects/03-thinklab-ikon.png\",\"alt\":\"ThinkLab — Ikon dari build aplikasi. Resolusi asli 192 piksel; jangan diperbesar untuk hero.\"}]},{\"title\":\"LEWU CBT\",\"sub\":\"Ujian digital tanpa internet\",\"cats\":[\"sekolah\",\"belajar\"],\"thumb\":\"lewu\",\"image\":\"\",\"deco\":\"tape\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Web lokal (LAN) + laptop Windows\",\"problem\":\"Ujian online gagal begitu sinyal putus.\",\"solution\":\"Laptop guru jadi server, siswa ujian lewat browser di Wi-Fi lokal. Login pakai QR Kelasku, soal PG/isian/esai, monitoring, ekspor, dan backup.\",\"users\":\"Guru/pengawas, siswa SMP\",\"stack\":\"Node.js · Express · SQLite · router Wi-Fi\",\"ai\":\"\",\"note\":\"Login QR sudah berhasil. Uji serentak satu kelas penuh belum tuntas.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/04-lewu-ruang-siswa.png\",\"alt\":\"LEWU CBT — Screenshot halaman siswa utuh.\"},{\"src\":\"assets/projects/04-lewu-maskot.png\",\"alt\":\"LEWU CBT — Maskot dari dokumentasi proyek.\"}]},{\"image\":\"\",\"link\":\"\",\"ai\":\"SIMFONI Intelligence: menganalisis perkembangan siswa, efektivitas program, dan ketercapaian visi-misi, lalu memberi rekomendasi berbasis data\",\"title\":\"SIMFONI\",\"sub\":\"Manajemen sekolah terintegrasi berbasis AI\",\"cats\":[\"sekolah\",\"ai\"],\"thumb\":\"simfoni\",\"deco\":\"tape\",\"statusType\":\"concept\",\"status\":\"\",\"platform\":\"Web + AI\",\"problem\":\"Data sekolah tersebar di banyak tempat, sehingga sulit melihat perkembangan siswa dan ketercapaian visi-misi secara utuh.\",\"solution\":\"Satu platform untuk administrasi, data siswa, absensi QR, pembelajaran, penilaian, jurnal harian, pembinaan karakter, literasi-numerasi, ekstrakurikuler, program sekolah, dan komunikasi dengan orang tua.\",\"users\":\"Kepala sekolah, guru, wali kelas, siswa, orang tua, tenaga kependidikan\",\"stack\":\"Web · arsitektur sedang disusun\",\"note\":\"Sistem Informasi Manajemen dan Fungsi Operasional Pendidikan Terintegrasi. Dirancang untuk SMP Negeri 7 Katingan Hilir; aplikasi mandiri, terpisah dari Kelasku.\"},{\"image\":\"\",\"link\":\"\",\"ai\":\"Gemini API\",\"title\":\"PenaPintar AI\",\"sub\":\"Generator soal ujian berbasis AI\",\"cats\":[\"ai\"],\"thumb\":\"pena\",\"deco\":\"tape\",\"statusType\":\"dev\",\"status\":\"\",\"platform\":\"Web app\",\"problem\":\"Menyusun butir soal itu lama, sementara pekerjaan guru banyak.\",\"solution\":\"Membantu guru menghasilkan soal ujian dengan bantuan AI generatif, sehingga waktu menyusun soal jadi lebih singkat.\",\"users\":\"Guru\",\"stack\":\"Python · Streamlit\",\"note\":\"Tampilan masih terus diperbarui.\"},{\"title\":\"BlockKode\",\"sub\":\"Koding blok + kuis tarik tambang\",\"cats\":[\"belajar\",\"web\"],\"thumb\":\"blockkode\",\"image\":\"\",\"deco\":\"tape\",\"statusType\":\"dev\",\"status\":\"\",\"platform\":\"Web (layar sentuh/IFP)\",\"problem\":\"Siswa pemula butuh cara yang ramah untuk memahami logika koding.\",\"solution\":\"Playground koding visual berbasis blok, ditambah kuis tarik tambang dua tim untuk dimainkan di depan kelas.\",\"users\":\"Siswa pemula\",\"stack\":\"HTML · CSS · JavaScript\",\"ai\":\"\",\"note\":\"Sudah pernah dibuat. Pengujian dan publikasinya masih dicek.\",\"link\":\"\"},{\"title\":\"MyStep\",\"sub\":\"Aplikasi tujuan & kebiasaan\",\"cats\":[\"android\"],\"thumb\":\"mystep\",\"image\":\"\",\"deco\":\"pin\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Android native\",\"problem\":\"Butuh satu tempat sederhana untuk tujuan, kebiasaan, dan tugas harian.\",\"solution\":\"Aplikasi Android untuk mengatur tujuan, kebiasaan, rutinitas, tugas, lalu melihat progresnya.\",\"users\":\"Pengguna pribadi\",\"stack\":\"Kotlin · Jetpack Compose · Android Studio · Gradle\",\"ai\":\"\",\"note\":\"Build berhasil dijalankan di emulator Android. Uji di HP asli menyusul; belum ada di Play Store.\",\"link\":\"\"},{\"title\":\"Q-Sat Edu\",\"sub\":\"Kantor virtual 3D dengan 10 agen AI\",\"cats\":[\"ai\"],\"thumb\":\"qsat\",\"image\":\"\",\"deco\":\"tape\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Web 3D lokal + backend Windows\",\"problem\":\"Mengelola banyak proyek sendirian butuh “tim” yang bisa diajak berbagi tugas.\",\"solution\":\"Ruang kerja 3D tempat 10 agen AI virtual membantu koordinasi, rapat, dan pemantauan proyek, tersambung ke bot Telegram.\",\"users\":\"Pengelola proyek\",\"stack\":\"Three.js · backend lokal · Telegram Bot API · Cloudflare Workers\",\"ai\":\"Router AI (Gemini, Groq, NVIDIA) + model Qwen lokal, diintegrasikan bertahap\",\"note\":\"Ini agen virtual, bukan pegawai manusia. Tidak semua jalur AI aktif bersamaan.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/09-qsat-kantor-3d.png\",\"alt\":\"Q-Sat Edu — Screenshot kantor 3D versi tersimpan.\"},{\"src\":\"assets/projects/09-qsat-logo.png\",\"alt\":\"Q-Sat Edu — Logo dari sumber proyek.\"}]},{\"title\":\"PIJAR\",\"sub\":\"Debugging Matematis — metode 5 langkah\",\"cats\":[\"belajar\"],\"thumb\":\"pijar\",\"image\":\"\",\"deco\":\"pin\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Metode + modul\",\"problem\":\"Penalaran dan numerasi butuh kebiasaan menguji lalu memperbaiki, bukan sekadar menghafal rumus.\",\"solution\":\"Lima langkah: Pahami Masalah → Identifikasi & Prediksi → Jalankan & Uji → Analisis & Perbaiki → Refleksi & Replikasi. Jawaban salah diperlakukan seperti bug yang bisa diperbaiki.\",\"users\":\"Guru dan siswa SMP\",\"stack\":\"Desain pembelajaran · modul · Lab Maya\",\"ai\":\"\",\"note\":\"PIJAR adalah metode, bukan aplikasi. Bukti dampaknya sedang dikumpulkan.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/10-pijar-penerapan-lab.png\",\"alt\":\"PIJAR — Penerapan PIJAR dalam Lab Maya; bukan aplikasi PIJAR terpisah.\"},{\"src\":\"assets/projects/10-pijar-lima-tahap-mobile.png\",\"alt\":\"PIJAR — Screenshot penerapan lima tahap PIJAR.\"}]},{\"image\":\"\",\"link\":\"\",\"ai\":\"\",\"title\":\"Step by Steph Tour\",\"sub\":\"Website wisata Lombok dwibahasa\",\"cats\":[\"web\"],\"thumb\":\"steph\",\"deco\":\"pin\",\"statusType\":\"dev\",\"status\":\"\",\"platform\":\"Website\",\"problem\":\"Pengelola tur butuh website yang meyakinkan wisatawan lokal dan mancanegara.\",\"solution\":\"Informasi destinasi, paket tur, galeri, dan kontak/pemesanan dalam bahasa Indonesia dan Inggris.\",\"users\":\"Wisatawan, pengelola tur\",\"stack\":\"WordPress · Elementor\",\"note\":\"Proyek berbayar untuk klien.\"},{\"title\":\"Web SMPN 7 Katingan Hilir\",\"sub\":\"Website profil sekolah\",\"cats\":[\"web\",\"sekolah\"],\"thumb\":\"sekolah\",\"image\":\"\",\"deco\":\"pin\",\"statusType\":\"dev\",\"status\":\"\",\"platform\":\"Website\",\"problem\":\"Sekolah butuh wajah resmi di internet untuk profil, berita, galeri, dan pengumuman.\",\"solution\":\"Website profil sekolah yang ringan dan mudah diperbarui.\",\"users\":\"Masyarakat, siswa, orang tua, sekolah\",\"stack\":\"HTML/CSS/JS · rencana domain .sch.id\",\"ai\":\"\",\"note\":\"Masih dikembangkan; belum tayang resmi.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/12-smpn7-program.png\",\"alt\":\"Program SMP Negeri 7 Katingan Hilir\"},{\"src\":\"assets/projects/12-smpn7-hero.png\",\"alt\":\"Beranda SMP Negeri 7 Katingan Hilir\"}]},{\"title\":\"SIAP Kelurahan\",\"sub\":\"Antrean & panduan layanan warga\",\"cats\":[\"web\"],\"thumb\":\"layanan\",\"image\":\"\",\"deco\":\"tape\",\"statusType\":\"concept\",\"status\":\"\",\"platform\":\"Web\",\"problem\":\"Warga perlu tahu syarat layanan dan kepastian antrean sebelum datang ke kantor kelurahan.\",\"solution\":\"Meja depan digital: pilih jenis layanan → ambil nomor antrean → dipanggil petugas → laporan untuk lurah.\",\"users\":\"Warga, petugas, lurah\",\"stack\":\"Rencana: HTML/CSS/JS · Cloudflare Pages · Supabase\",\"ai\":\"\",\"note\":\"Masih berupa project brief dan rancangan rinci, belum menjadi layanan resmi.\",\"link\":\"\",\"images\":[{\"src\":\"assets/projects/13-siap-kelurahan-beranda-mobile.jpeg\",\"alt\":\"SIAP Kelurahan — Beranda pelayanan terbaru dari pengguna.\"},{\"src\":\"assets/projects/13-siap-kelurahan-login-mobile.jpeg\",\"alt\":\"SIAP Kelurahan — Tampilan login terbaru dari pengguna.\"},{\"src\":\"assets/projects/13-siap-kelurahan-logo.png\",\"alt\":\"SIAP Kelurahan — Logo dari sumber proyek.\"}]},{\"title\":\"Cepat Tepat Pangkat\",\"sub\":\"Kuis kelompok bilangan berpangkat\",\"cats\":[\"belajar\",\"web\"],\"thumb\":\"ide\",\"image\":\"assets/projects/pangkat.png\",\"deco\":\"pin\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Website\",\"problem\":\"Latihan bilangan berpangkat memerlukan media kuis kelompok yang interaktif.\",\"solution\":\"Permainan kuis bilangan berpangkat dengan layar kelompok.\",\"users\":\"Siswa dan guru matematika\",\"stack\":\"HTML / CSS / JavaScript\",\"ai\":\"\",\"note\":\"Tampilan diambil dari sumber proyek lokal. Status publikasi belum diverifikasi.\",\"link\":\"\"},{\"title\":\"Math Strike Force\",\"sub\":\"Permainan matematika interaktif\",\"cats\":[\"belajar\",\"web\"],\"thumb\":\"ide\",\"image\":\"assets/projects/math-strike.png\",\"deco\":\"pin\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Website\",\"problem\":\"Latihan operasi hitung membutuhkan variasi aktivitas.\",\"solution\":\"Permainan matematika bertema robot dengan misi penjumlahan.\",\"users\":\"Siswa dan guru matematika\",\"stack\":\"HTML / CSS / JavaScript\",\"ai\":\"\",\"note\":\"Tampilan diambil dari sumber proyek lokal. Status publikasi belum diverifikasi.\",\"link\":\"\"},{\"title\":\"SMP Negeri 5 Sanaman Mantikei\",\"sub\":\"Website profil sekolah\",\"cats\":[\"sekolah\",\"web\"],\"thumb\":\"ide\",\"image\":\"assets/projects/smpn5.png\",\"deco\":\"pin\",\"statusType\":\"proto\",\"status\":\"\",\"platform\":\"Website\",\"problem\":\"Informasi dan dokumentasi sekolah perlu disajikan dalam satu website.\",\"solution\":\"Website profil sekolah dengan halaman profil, akademik, galeri, berita, dan kontak.\",\"users\":\"Warga sekolah dan masyarakat\",\"stack\":\"HTML / CSS / JavaScript\",\"ai\":\"\",\"note\":\"Tampilan diambil dari sumber proyek lokal. Status publikasi belum diverifikasi.\",\"link\":\"\"}],\"moreLabel\":\"Ikuti prosesnya di Instagram\",\"moreLink\":\"https://instagram.com/kelasmrk\",\"initial\":9,\"moreAll\":\"Tampilkan semua karya\"},\"expertise\":{\"title\":\"Keahlian\",\"intro\":\"Tiga hal yang saya kerjakan dan praktikkan langsung di sekolah, bukan sekadar teori.\",\"cards\":[{\"icon\":\"school\",\"title\":\"Sistem Sekolah\",\"desc\":\"Administrasi rapi, data siswa terjaga, dan bisa dirawat sendiri oleh sekolah.\",\"items\":[\"Presensi QR, nilai, rapor\",\"Ujian offline lewat Wi-Fi lokal\",\"Website profil sekolah\"],\"link\":\"Lihat proyek →\",\"go\":\"sekolah\"},{\"icon\":\"game\",\"title\":\"Media Pembelajaran & STEM\",\"desc\":\"Belajar dari konteks sendiri, tetap jalan di HP, IFP, atau tanpa internet.\",\"items\":[\"Simulasi numerasi berbasis kearifan lokal\",\"Koding blok untuk pemula\",\"Metode PIJAR untuk penalaran\"],\"link\":\"Lihat proyek →\",\"go\":\"belajar\"},{\"icon\":\"talk\",\"title\":\"Narasumber & Pelatihan\",\"desc\":\"Berbagi dari pengalaman nyata membangun di sekolah 3T.\",\"items\":[\"AI untuk guru, dipakai dengan jujur & aman\",\"Koding & KA di SMP\",\"Membangun aplikasi sekolah sendiri\"],\"link\":\"Undang saya →\",\"go\":\"contact\"}]},\"stack\":{\"label\":\"Teknologi & AI\",\"titleHl\":\"Alat\",\"title\":\"yang dipakai\",\"intro\":\"\",\"groups\":[{\"title\":\"Bahasa pemrograman\",\"note\":\"\",\"items\":[\"JavaScript\",\"TypeScript\",\"Python\",\"Kotlin\",\"Java\",\"SQL\",\"HTML\",\"CSS\",\"JSON\"]},{\"title\":\"Backend & framework\",\"note\":\"\",\"items\":[\"Node.js\",\"Express.js\",\"Flask\",\"Three.js\",\"API REST\",\"Local Server\"]},{\"title\":\"Python & aplikasi desktop\",\"note\":\"\",\"items\":[\"Tkinter\",\"Pandas\",\"PySide6\",\"PyInstaller\",\"Windows\",\"PowerShell\"]},{\"title\":\"Android & mobile\",\"note\":\"\",\"items\":[\"Jetpack Compose\",\"Gradle\",\"Android Studio\",\"Android SDK\",\"Android Emulator\",\"Android WebView\",\"Capacitor\",\"Cordova\",\"TWA\",\"PWA\",\"APK\"]},{\"title\":\"Database & cloud\",\"note\":\"\",\"items\":[\"Supabase\",\"PostgreSQL\",\"SQLite\",\"Firebase\",\"Firestore\",\"Firebase Authentication\",\"Google Cloud Run\",\"Google Cloud Secret Manager\",\"BigQuery MCP Server\"]},{\"title\":\"Hosting & versi kode\",\"note\":\"\",\"items\":[\"GitHub\",\"Git\",\"GitHub Actions\",\"Cloudflare Pages\",\"Cloudflare Workers\",\"WordPress\",\"Elementor\"]},{\"title\":\"AI & model\",\"note\":\"\",\"items\":[\"ChatGPT\",\"ChatGPT Work\",\"OpenAI API\",\"Google Gemini\",\"Gemini API\",\"Google AI Studio\",\"Gemini Canvas\",\"Groq API\",\"NVIDIA AI API\",\"Qwen\",\"Ollama\"]},{\"title\":\"Agen AI & otomasi\",\"note\":\"\",\"items\":[\"LangChain\",\"RAG\",\"Google ADK\",\"AI Agents\",\"Multi-Agent System\",\"Prompt Engineering\",\"Automation\"]},{\"title\":\"Suara & bot\",\"note\":\"\",\"items\":[\"Whisper\",\"Vosk\",\"Piper TTS\",\"Telegram Bot API\",\"WhatsApp Business Platform\"]},{\"title\":\"Sekolah offline\",\"note\":\"\",\"items\":[\"LAN\",\"Wi-Fi Router\",\"Offline-First\",\"QR Code\",\"Tailscale\"]},{\"title\":\"Desain & dokumen\",\"note\":\"\",\"items\":[\"UI/UX Design\",\"Wireframe\",\"Prototyping\",\"Canva\",\"Canva AI Code\",\"Argon\",\"Mermaid\",\"Word\",\"CSV\",\"Excel\",\"PDF\"]},{\"title\":\"Cara kerja\",\"note\":\"\",\"items\":[\"Debugging\",\"Testing\",\"Deployment\",\"Browser Developer Tools\"]}]},\"process\":{\"label\":\"Cara kerja\",\"titleHl\":\"6 langkah\",\"title\":\"dari masalah ke solusi\",\"steps\":[{\"title\":\"Masalah\",\"sub\":\"siapa kesulitan apa?\",\"text\":\"Mulai dari kelas: siapa yang kesulitan, perangkat apa yang ada, sinyalnya bagaimana.\"},{\"title\":\"Ide\",\"sub\":\"sederhana, murah, aman\",\"text\":\"Pilih solusi paling sederhana yang benar-benar bisa dipakai. Fitur canggih menunggu.\"},{\"title\":\"Sketsa\",\"sub\":\"alur & tampilan\",\"text\":\"Alur pengguna, wireframe, dan rancangan data, termasuk siapa boleh melihat data siswa.\"},{\"title\":\"Bangun\",\"sub\":\"kode & build\",\"text\":\"Membangun fitur inti dengan alat yang cocok, dibantu AI, kode tersimpan rapi di GitHub.\"},{\"title\":\"Uji\",\"sub\":\"di perangkat asli\",\"text\":\"Dites di HP dan laptop sungguhan, juga dengan internet benar-benar mati. Hasilnya dicatat apa adanya.\"},{\"title\":\"Serahkan\",\"sub\":\"panduan & pendampingan\",\"text\":\"Demo, panduan, dan cadangan data supaya pengguna bisa merawatnya sendiri.\"}],\"workedGroups\":[{\"label\":\"Sekolah, instansi & klien\",\"items\":[\"SMPN 5 Sanaman Mantikei\",\"SMPN 7 Katingan Hilir\",\"SD Negeri Tumbang Kawei\",\"Kelurahan Kasongan Lama\",\"Klinik Lapas Kelas II Palangka Raya\",\"Rumah Sehat Pendarawah\",\"Step by Steph Tour\",\"Asian Trail\"]},{\"label\":\"Program, pelatihan & komunitas\",\"items\":[\"ZEP Quiz · Global Ambassador 2026\",\"Gemini for Educators\",\"Dicoding\",\"DBS Foundation\",\"Baparekraf\",\"Maju Bareng AI\",\"Hacktiv8 Indonesia\",\"Komunitas Dev Indonesia\",\"Tegal.Dev\"]}]},\"contact\":{\"label\":\"Kontak\",\"title\":\"Yuk kerja\\nsama\",\"lead\":\"Mau membangun sistem untuk sekolah, mengundang narasumber, atau ngobrol soal AI di kelas? Kirim pesan saja.\",\"email\":\"kristantosaputra2@gmail.com\",\"socials\":{\"instagram\":\"https://instagram.com/kelasmrk\",\"tiktok\":\"\",\"youtube\":\"\",\"whatsapp\":\"\",\"facebook\":\"\",\"linkedin\":\"\",\"website\":\"\"},\"formTitle\":\"Kirim catatan singkat\",\"purposes\":[\"Undangan narasumber\",\"Sistem/aplikasi sekolah\",\"Website sekolah\",\"Media pembelajaran\",\"Lainnya\"]},\"footer\":{\"copy\":\"Kristanto Saputra · Kelas Mr.K. Dibuat dari pedalaman Kalimantan Tengah.\",\"base\":\"Mendidik dari pedalaman, membangun untuk Indonesia.\"},\"support\":{\"enabled\":false,\"mode\":\"link\",\"title\":\"Traktir Kopi\",\"message\":\"Jika catatan dan karya ini bermanfaat, kamu bisa mendukung pengembangannya dengan traktir kopi. Dukungan sepenuhnya sukarela.\",\"buttonLabel\":\"Traktir Kopi ☕\",\"url\":\"\"}}","version":1,"updated":"2026-11-24T09:09:33.258Z"}','2026-11-24T09:09:33.258Z');
INSERT OR IGNORE INTO items(id,kind,slug,draft,published,version,updated) VALUES('tutorial-kuis','tutorial','membuat-kuis-html-dengan-ai','{"summary":"Dari prompt awal sampai game yang dapat dibuka tanpa internet. Termasuk demo kuis dan langkah memeriksa hasil.","category":"Gamifikasi HTML","cover":"","video":"","body":"Panduan ini memakai instruksi yang bisa ditempel ke AI pilihanmu. Nama menu dan kemampuan menghasilkan file dapat berbeda antar layanan. Tidak ada jaminan hasil identik: periksa materi dan fungsi sebelum dipakai di kelas.\n\nDemo yang disertakan adalah kuis perkalian sederhana, bukan hasil yang dijanjikan dari setiap AI. Buka demo sebagai contoh alur dan tampilan.","version":"","requirements":"","readiness":"","license":"","links":{"download":"/demo/kuis-mandiri.html","demo":"/demo/kuis.html","source":"","issues":"","guide":""},"steps":[{"title":"Tentukan kebutuhan, lalu buat versi awal","text":"Pilih tujuan pembelajaran dan kondisi perangkat. Salin prompt berikut atau buka Sesuaikan prompt ini. Setelah mendapat kode, salin hanya isi blok HTML ke editor teks, simpan sebagai index.html (bukan .txt), lalu buka di browser.","prompt":"Buat game kuis pembelajaran {{mapel}} untuk kelas {{kelas}}, topik {{topik}}, dengan tema {{tema}}. Buat {{jumlah}} soal dan optimalkan untuk {{perangkat}}.\n\nTujuan: siswa berlatih memahami materi melalui kuis dengan umpan balik yang jelas.\n\nHasilkan satu file HTML lengkap yang berisi CSS dan JavaScript di dalamnya. Tanpa pustaka, font, gambar, API, atau koneksi internet eksternal. Gunakan tombol besar, teks mudah dibaca, serta tampilan responsif. Sediakan petunjuk, tombol mulai, satu soal per layar, skor, penjelasan jawaban, dan tombol ulang. Jawaban hanya dapat dinilai sekali per soal. Jangan gunakan timer sebagai syarat kelulusan.\n\nTuliskan soal dan kunci yang dapat diperiksa guru. Jika ada materi ambigu, jelaskan asumsi. Jangan menambahkan formulir pengumpulan data pribadi.\n\nKeluarkan kode HTML utuh dalam satu blok, lalu jelaskan cara menyimpan sebagai index.html dan membukanya di browser. Sebutkan bagian yang masih perlu diperiksa guru."},{"title":"Periksa materi dan aturan skor","text":"Kerjakan seluruh soal sendiri. Pastikan kunci benar, penjelasan sesuai, dan jawaban tidak bisa diklik berkali-kali untuk menambah skor.","prompt":"Periksa kode game HTML yang saya tempel di bawah. Audit kebenaran soal, kunci jawaban, perhitungan skor, dan perilaku tombol. Daftarkan masalah yang ditemukan. Pertahankan tujuan serta tampilan yang sudah ada. Jika ada masalah, keluarkan satu file HTML lengkap yang telah diperbaiki. Jangan mengaku sudah menguji browser jika belum.\n\n[Tempel kode HTML game di sini]"},{"title":"Uji di HP dan tanpa internet","text":"Buka di layar kecil. Coba tombol mulai, setiap pilihan jawaban, lanjut, hasil, dan ulang. Matikan internet dan muat ulang file. Jika ada masalah, jelaskan gejala dan perangkat kepada AI.","prompt":"Perbaiki game HTML berikut untuk masalah ini: [jelaskan gejala dan langkah mengulangnya]. Perangkat/browser: [isi]. Pertahankan soal dan desain sejauh memungkinkan. Pastikan tetap satu file dan tidak memerlukan internet. Jelaskan perubahan, lalu berikan file HTML lengkap.\n\n[Tempel kode HTML di sini]"}],"fields":[{"key":"mapel","label":"Mata pelajaran","type":"text","default":"Matematika","options":[]},{"key":"kelas","label":"Kelas","type":"text","default":"VIII SMP","options":[]},{"key":"topik","label":"Topik pembelajaran","type":"text","default":"Bilangan berpangkat","options":[]},{"key":"tema","label":"Tema permainan","type":"text","default":"Ekspedisi hutan Kalimantan","options":[]},{"key":"jumlah","label":"Jumlah soal","type":"select","default":"5","options":["5","10","15"]},{"key":"perangkat","label":"Perangkat utama","type":"select","default":"HP dan laptop","options":["HP dan laptop","Laptop","Layar kelas / IFP"]}],"template":"Buat game kuis pembelajaran {{mapel}} untuk kelas {{kelas}}, topik {{topik}}, dengan tema {{tema}}. Buat {{jumlah}} soal dan optimalkan untuk {{perangkat}}.\n\nTujuan: siswa berlatih memahami materi melalui kuis dengan umpan balik yang jelas.\n\nHasilkan satu file HTML lengkap yang berisi CSS dan JavaScript di dalamnya. Tanpa pustaka, font, gambar, API, atau koneksi internet eksternal. Gunakan tombol besar, teks mudah dibaca, serta tampilan responsif. Sediakan petunjuk, tombol mulai, satu soal per layar, skor, penjelasan jawaban, dan tombol ulang. Jawaban hanya dapat dinilai sekali per soal. Jangan gunakan timer sebagai syarat kelulusan.\n\nTuliskan soal dan kunci yang dapat diperiksa guru. Jika ada materi ambigu, jelaskan asumsi. Jangan menambahkan formulir pengumpulan data pribadi.\n\nKeluarkan kode HTML utuh dalam satu blok, lalu jelaskan cara menyimpan sebagai index.html dan membukanya di browser. Sebutkan bagian yang masih perlu diperiksa guru.","related":["prompt-kuis"],"title":"Membuat kuis HTML dengan bantuan AI"}','{"summary":"Dari prompt awal sampai game yang dapat dibuka tanpa internet. Termasuk demo kuis dan langkah memeriksa hasil.","category":"Gamifikasi HTML","cover":"","video":"","body":"Panduan ini memakai instruksi yang bisa ditempel ke AI pilihanmu. Nama menu dan kemampuan menghasilkan file dapat berbeda antar layanan. Tidak ada jaminan hasil identik: periksa materi dan fungsi sebelum dipakai di kelas.\n\nDemo yang disertakan adalah kuis perkalian sederhana, bukan hasil yang dijanjikan dari setiap AI. Buka demo sebagai contoh alur dan tampilan.","version":"","requirements":"","readiness":"","license":"","links":{"download":"/demo/kuis-mandiri.html","demo":"/demo/kuis.html","source":"","issues":"","guide":""},"steps":[{"title":"Tentukan kebutuhan, lalu buat versi awal","text":"Pilih tujuan pembelajaran dan kondisi perangkat. Salin prompt berikut atau buka Sesuaikan prompt ini. Setelah mendapat kode, salin hanya isi blok HTML ke editor teks, simpan sebagai index.html (bukan .txt), lalu buka di browser.","prompt":"Buat game kuis pembelajaran {{mapel}} untuk kelas {{kelas}}, topik {{topik}}, dengan tema {{tema}}. Buat {{jumlah}} soal dan optimalkan untuk {{perangkat}}.\n\nTujuan: siswa berlatih memahami materi melalui kuis dengan umpan balik yang jelas.\n\nHasilkan satu file HTML lengkap yang berisi CSS dan JavaScript di dalamnya. Tanpa pustaka, font, gambar, API, atau koneksi internet eksternal. Gunakan tombol besar, teks mudah dibaca, serta tampilan responsif. Sediakan petunjuk, tombol mulai, satu soal per layar, skor, penjelasan jawaban, dan tombol ulang. Jawaban hanya dapat dinilai sekali per soal. Jangan gunakan timer sebagai syarat kelulusan.\n\nTuliskan soal dan kunci yang dapat diperiksa guru. Jika ada materi ambigu, jelaskan asumsi. Jangan menambahkan formulir pengumpulan data pribadi.\n\nKeluarkan kode HTML utuh dalam satu blok, lalu jelaskan cara menyimpan sebagai index.html dan membukanya di browser. Sebutkan bagian yang masih perlu diperiksa guru."},{"title":"Periksa materi dan aturan skor","text":"Kerjakan seluruh soal sendiri. Pastikan kunci benar, penjelasan sesuai, dan jawaban tidak bisa diklik berkali-kali untuk menambah skor.","prompt":"Periksa kode game HTML yang saya tempel di bawah. Audit kebenaran soal, kunci jawaban, perhitungan skor, dan perilaku tombol. Daftarkan masalah yang ditemukan. Pertahankan tujuan serta tampilan yang sudah ada. Jika ada masalah, keluarkan satu file HTML lengkap yang telah diperbaiki. Jangan mengaku sudah menguji browser jika belum.\n\n[Tempel kode HTML game di sini]"},{"title":"Uji di HP dan tanpa internet","text":"Buka di layar kecil. Coba tombol mulai, setiap pilihan jawaban, lanjut, hasil, dan ulang. Matikan internet dan muat ulang file. Jika ada masalah, jelaskan gejala dan perangkat kepada AI.","prompt":"Perbaiki game HTML berikut untuk masalah ini: [jelaskan gejala dan langkah mengulangnya]. Perangkat/browser: [isi]. Pertahankan soal dan desain sejauh memungkinkan. Pastikan tetap satu file dan tidak memerlukan internet. Jelaskan perubahan, lalu berikan file HTML lengkap.\n\n[Tempel kode HTML di sini]"}],"fields":[{"key":"mapel","label":"Mata pelajaran","type":"text","default":"Matematika","options":[]},{"key":"kelas","label":"Kelas","type":"text","default":"VIII SMP","options":[]},{"key":"topik","label":"Topik pembelajaran","type":"text","default":"Bilangan berpangkat","options":[]},{"key":"tema","label":"Tema permainan","type":"text","default":"Ekspedisi hutan Kalimantan","options":[]},{"key":"jumlah","label":"Jumlah soal","type":"select","default":"5","options":["5","10","15"]},{"key":"perangkat","label":"Perangkat utama","type":"select","default":"HP dan laptop","options":["HP dan laptop","Laptop","Layar kelas / IFP"]}],"template":"Buat game kuis pembelajaran {{mapel}} untuk kelas {{kelas}}, topik {{topik}}, dengan tema {{tema}}. Buat {{jumlah}} soal dan optimalkan untuk {{perangkat}}.\n\nTujuan: siswa berlatih memahami materi melalui kuis dengan umpan balik yang jelas.\n\nHasilkan satu file HTML lengkap yang berisi CSS dan JavaScript di dalamnya. Tanpa pustaka, font, gambar, API, atau koneksi internet eksternal. Gunakan tombol besar, teks mudah dibaca, serta tampilan responsif. Sediakan petunjuk, tombol mulai, satu soal per layar, skor, penjelasan jawaban, dan tombol ulang. Jawaban hanya dapat dinilai sekali per soal. Jangan gunakan timer sebagai syarat kelulusan.\n\nTuliskan soal dan kunci yang dapat diperiksa guru. Jika ada materi ambigu, jelaskan asumsi. Jangan menambahkan formulir pengumpulan data pribadi.\n\nKeluarkan kode HTML utuh dalam satu blok, lalu jelaskan cara menyimpan sebagai index.html dan membukanya di browser. Sebutkan bagian yang masih perlu diperiksa guru.","related":["prompt-kuis"],"title":"Membuat kuis HTML dengan bantuan AI"}',1,'2026-11-24T09:09:33.261Z');
INSERT OR IGNORE INTO revisions(id,item_id,action,snapshot,created) VALUES('seed-tutorial-kuis','tutorial-kuis','Versi awal','{"id":"tutorial-kuis","kind":"tutorial","slug":"membuat-kuis-html-dengan-ai","draft":"{\"summary\":\"Dari prompt awal sampai game yang dapat dibuka tanpa internet. Termasuk demo kuis dan langkah memeriksa hasil.\",\"category\":\"Gamifikasi HTML\",\"cover\":\"\",\"video\":\"\",\"body\":\"Panduan ini memakai instruksi yang bisa ditempel ke AI pilihanmu. Nama menu dan kemampuan menghasilkan file dapat berbeda antar layanan. Tidak ada jaminan hasil identik: periksa materi dan fungsi sebelum dipakai di kelas.\\n\\nDemo yang disertakan adalah kuis perkalian sederhana, bukan hasil yang dijanjikan dari setiap AI. Buka demo sebagai contoh alur dan tampilan.\",\"version\":\"\",\"requirements\":\"\",\"readiness\":\"\",\"license\":\"\",\"links\":{\"download\":\"/demo/kuis-mandiri.html\",\"demo\":\"/demo/kuis.html\",\"source\":\"\",\"issues\":\"\",\"guide\":\"\"},\"steps\":[{\"title\":\"Tentukan kebutuhan, lalu buat versi awal\",\"text\":\"Pilih tujuan pembelajaran dan kondisi perangkat. Salin prompt berikut atau buka Sesuaikan prompt ini. Setelah mendapat kode, salin hanya isi blok HTML ke editor teks, simpan sebagai index.html (bukan .txt), lalu buka di browser.\",\"prompt\":\"Buat game kuis pembelajaran {{mapel}} untuk kelas {{kelas}}, topik {{topik}}, dengan tema {{tema}}. Buat {{jumlah}} soal dan optimalkan untuk {{perangkat}}.\\n\\nTujuan: siswa berlatih memahami materi melalui kuis dengan umpan balik yang jelas.\\n\\nHasilkan satu file HTML lengkap yang berisi CSS dan JavaScript di dalamnya. Tanpa pustaka, font, gambar, API, atau koneksi internet eksternal. Gunakan tombol besar, teks mudah dibaca, serta tampilan responsif. Sediakan petunjuk, tombol mulai, satu soal per layar, skor, penjelasan jawaban, dan tombol ulang. Jawaban hanya dapat dinilai sekali per soal. Jangan gunakan timer sebagai syarat kelulusan.\\n\\nTuliskan soal dan kunci yang dapat diperiksa guru. Jika ada materi ambigu, jelaskan asumsi. Jangan menambahkan formulir pengumpulan data pribadi.\\n\\nKeluarkan kode HTML utuh dalam satu blok, lalu jelaskan cara menyimpan sebagai index.html dan membukanya di browser. Sebutkan bagian yang masih perlu diperiksa guru.\"},{\"title\":\"Periksa materi dan aturan skor\",\"text\":\"Kerjakan seluruh soal sendiri. Pastikan kunci benar, penjelasan sesuai, dan jawaban tidak bisa diklik berkali-kali untuk menambah skor.\",\"prompt\":\"Periksa kode game HTML yang saya tempel di bawah. Audit kebenaran soal, kunci jawaban, perhitungan skor, dan perilaku tombol. Daftarkan masalah yang ditemukan. Pertahankan tujuan serta tampilan yang sudah ada. Jika ada masalah, keluarkan satu file HTML lengkap yang telah diperbaiki. Jangan mengaku sudah menguji browser jika belum.\\n\\n[Tempel kode HTML game di sini]\"},{\"title\":\"Uji di HP dan tanpa internet\",\"text\":\"Buka di layar kecil. Coba tombol mulai, setiap pilihan jawaban, lanjut, hasil, dan ulang. Matikan internet dan muat ulang file. Jika ada masalah, jelaskan gejala dan perangkat kepada AI.\",\"prompt\":\"Perbaiki game HTML berikut untuk masalah ini: [jelaskan gejala dan langkah mengulangnya]. Perangkat/browser: [isi]. Pertahankan soal dan desain sejauh memungkinkan. Pastikan tetap satu file dan tidak memerlukan internet. Jelaskan perubahan, lalu berikan file HTML lengkap.\\n\\n[Tempel kode HTML di sini]\"}],\"fields\":[{\"key\":\"mapel\",\"label\":\"Mata pelajaran\",\"type\":\"text\",\"default\":\"Matematika\",\"options\":[]},{\"key\":\"kelas\",\"label\":\"Kelas\",\"type\":\"text\",\"default\":\"VIII SMP\",\"options\":[]},{\"key\":\"topik\",\"label\":\"Topik pembelajaran\",\"type\":\"text\",\"default\":\"Bilangan berpangkat\",\"options\":[]},{\"key\":\"tema\",\"label\":\"Tema permainan\",\"type\":\"text\",\"default\":\"Ekspedisi hutan Kalimantan\",\"options\":[]},{\"key\":\"jumlah\",\"label\":\"Jumlah soal\",\"type\":\"select\",\"default\":\"5\",\"options\":[\"5\",\"10\",\"15\"]},{\"key\":\"perangkat\",\"label\":\"Perangkat utama\",\"type\":\"select\",\"default\":\"HP dan laptop\",\"options\":[\"HP dan laptop\",\"Laptop\",\"Layar kelas / IFP\"]}],\"template\":\"Buat game kuis pembelajaran {{mapel}} untuk kelas {{kelas}}, topik {{topik}}, dengan tema {{tema}}. Buat {{jumlah}} soal dan optimalkan untuk {{perangkat}}.\\n\\nTujuan: siswa berlatih memahami materi melalui kuis dengan umpan balik yang jelas.\\n\\nHasilkan satu file HTML lengkap yang berisi CSS dan JavaScript di dalamnya. Tanpa pustaka, font, gambar, API, atau koneksi internet eksternal. Gunakan tombol besar, teks mudah dibaca, serta tampilan responsif. Sediakan petunjuk, tombol mulai, satu soal per layar, skor, penjelasan jawaban, dan tombol ulang. Jawaban hanya dapat dinilai sekali per soal. Jangan gunakan timer sebagai syarat kelulusan.\\n\\nTuliskan soal dan kunci yang dapat diperiksa guru. Jika ada materi ambigu, jelaskan asumsi. Jangan menambahkan formulir pengumpulan data pribadi.\\n\\nKeluarkan kode HTML utuh dalam satu blok, lalu jelaskan cara menyimpan sebagai index.html dan membukanya di browser. Sebutkan bagian yang masih perlu diperiksa guru.\",\"related\":[\"prompt-kuis\"],\"title\":\"Membuat kuis HTML dengan bantuan AI\"}","published":"{\"summary\":\"Dari prompt awal sampai game yang dapat dibuka tanpa internet. Termasuk demo kuis dan langkah memeriksa hasil.\",\"category\":\"Gamifikasi HTML\",\"cover\":\"\",\"video\":\"\",\"body\":\"Panduan ini memakai instruksi yang bisa ditempel ke AI pilihanmu. Nama menu dan kemampuan menghasilkan file dapat berbeda antar layanan. Tidak ada jaminan hasil identik: periksa materi dan fungsi sebelum dipakai di kelas.\\n\\nDemo yang disertakan adalah kuis perkalian sederhana, bukan hasil yang dijanjikan dari setiap AI. Buka demo sebagai contoh alur dan tampilan.\",\"version\":\"\",\"requirements\":\"\",\"readiness\":\"\",\"license\":\"\",\"links\":{\"download\":\"/demo/kuis-mandiri.html\",\"demo\":\"/demo/kuis.html\",\"source\":\"\",\"issues\":\"\",\"guide\":\"\"},\"steps\":[{\"title\":\"Tentukan kebutuhan, lalu buat versi awal\",\"text\":\"Pilih tujuan pembelajaran dan kondisi perangkat. Salin prompt berikut atau buka Sesuaikan prompt ini. Setelah mendapat kode, salin hanya isi blok HTML ke editor teks, simpan sebagai index.html (bukan .txt), lalu buka di browser.\",\"prompt\":\"Buat game kuis pembelajaran {{mapel}} untuk kelas {{kelas}}, topik {{topik}}, dengan tema {{tema}}. Buat {{jumlah}} soal dan optimalkan untuk {{perangkat}}.\\n\\nTujuan: siswa berlatih memahami materi melalui kuis dengan umpan balik yang jelas.\\n\\nHasilkan satu file HTML lengkap yang berisi CSS dan JavaScript di dalamnya. Tanpa pustaka, font, gambar, API, atau koneksi internet eksternal. Gunakan tombol besar, teks mudah dibaca, serta tampilan responsif. Sediakan petunjuk, tombol mulai, satu soal per layar, skor, penjelasan jawaban, dan tombol ulang. Jawaban hanya dapat dinilai sekali per soal. Jangan gunakan timer sebagai syarat kelulusan.\\n\\nTuliskan soal dan kunci yang dapat diperiksa guru. Jika ada materi ambigu, jelaskan asumsi. Jangan menambahkan formulir pengumpulan data pribadi.\\n\\nKeluarkan kode HTML utuh dalam satu blok, lalu jelaskan cara menyimpan sebagai index.html dan membukanya di browser. Sebutkan bagian yang masih perlu diperiksa guru.\"},{\"title\":\"Periksa materi dan aturan skor\",\"text\":\"Kerjakan seluruh soal sendiri. Pastikan kunci benar, penjelasan sesuai, dan jawaban tidak bisa diklik berkali-kali untuk menambah skor.\",\"prompt\":\"Periksa kode game HTML yang saya tempel di bawah. Audit kebenaran soal, kunci jawaban, perhitungan skor, dan perilaku tombol. Daftarkan masalah yang ditemukan. Pertahankan tujuan serta tampilan yang sudah ada. Jika ada masalah, keluarkan satu file HTML lengkap yang telah diperbaiki. Jangan mengaku sudah menguji browser jika belum.\\n\\n[Tempel kode HTML game di sini]\"},{\"title\":\"Uji di HP dan tanpa internet\",\"text\":\"Buka di layar kecil. Coba tombol mulai, setiap pilihan jawaban, lanjut, hasil, dan ulang. Matikan internet dan muat ulang file. Jika ada masalah, jelaskan gejala dan perangkat kepada AI.\",\"prompt\":\"Perbaiki game HTML berikut untuk masalah ini: [jelaskan gejala dan langkah mengulangnya]. Perangkat/browser: [isi]. Pertahankan soal dan desain sejauh memungkinkan. Pastikan tetap satu file dan tidak memerlukan internet. Jelaskan perubahan, lalu berikan file HTML lengkap.\\n\\n[Tempel kode HTML di sini]\"}],\"fields\":[{\"key\":\"mapel\",\"label\":\"Mata pelajaran\",\"type\":\"text\",\"default\":\"Matematika\",\"options\":[]},{\"key\":\"kelas\",\"label\":\"Kelas\",\"type\":\"text\",\"default\":\"VIII SMP\",\"options\":[]},{\"key\":\"topik\",\"label\":\"Topik pembelajaran\",\"type\":\"text\",\"default\":\"Bilangan berpangkat\",\"options\":[]},{\"key\":\"tema\",\"label\":\"Tema permainan\",\"type\":\"text\",\"default\":\"Ekspedisi hutan Kalimantan\",\"options\":[]},{\"key\":\"jumlah\",\"label\":\"Jumlah soal\",\"type\":\"select\",\"default\":\"5\",\"options\":[\"5\",\"10\",\"15\"]},{\"key\":\"perangkat\",\"label\":\"Perangkat utama\",\"type\":\"select\",\"default\":\"HP dan laptop\",\"options\":[\"HP dan laptop\",\"Laptop\",\"Layar kelas / IFP\"]}],\"template\":\"Buat game kuis pembelajaran {{mapel}} untuk kelas {{kelas}}, topik {{topik}}, dengan tema {{tema}}. Buat {{jumlah}} soal dan optimalkan untuk {{perangkat}}.\\n\\nTujuan: siswa berlatih memahami materi melalui kuis dengan umpan balik yang jelas.\\n\\nHasilkan satu file HTML lengkap yang berisi CSS dan JavaScript di dalamnya. Tanpa pustaka, font, gambar, API, atau koneksi internet eksternal. Gunakan tombol besar, teks mudah dibaca, serta tampilan responsif. Sediakan petunjuk, tombol mulai, satu soal per layar, skor, penjelasan jawaban, dan tombol ulang. Jawaban hanya dapat dinilai sekali per soal. Jangan gunakan timer sebagai syarat kelulusan.\\n\\nTuliskan soal dan kunci yang dapat diperiksa guru. Jika ada materi ambigu, jelaskan asumsi. Jangan menambahkan formulir pengumpulan data pribadi.\\n\\nKeluarkan kode HTML utuh dalam satu blok, lalu jelaskan cara menyimpan sebagai index.html dan membukanya di browser. Sebutkan bagian yang masih perlu diperiksa guru.\",\"related\":[\"prompt-kuis\"],\"title\":\"Membuat kuis HTML dengan bantuan AI\"}","version":1,"updated":"2026-11-24T09:09:33.261Z"}','2026-11-24T09:09:33.261Z');
INSERT OR IGNORE INTO items(id,kind,slug,draft,published,version,updated) VALUES('prompt-kuis','prompt','prompt-kuis-html','{"summary":"Isi kelas, topik, tema, dan perangkat. Salin prompt hasil penyesuaian ke AI pilihanmu.","category":"Pembelajaran","cover":"","video":"","body":"Generator ini merangkai template di browser. Tidak mengirim isian ke layanan AI dan tidak membutuhkan kunci API. Setelah menyalin, tempel ke AI pilihanmu. Hasil kode tetap perlu diperiksa guru.","version":"","requirements":"","readiness":"","license":"","links":{"download":"","demo":"","source":"","issues":"","guide":""},"steps":[{"title":"Prompt dasar","text":"Gunakan langsung atau sesuaikan melalui formulir di bawah.","prompt":"Buat game kuis pembelajaran {{mapel}} untuk kelas {{kelas}}, topik {{topik}}, dengan tema {{tema}}. Buat {{jumlah}} soal dan optimalkan untuk {{perangkat}}.\n\nTujuan: siswa berlatih memahami materi melalui kuis dengan umpan balik yang jelas.\n\nHasilkan satu file HTML lengkap yang berisi CSS dan JavaScript di dalamnya. Tanpa pustaka, font, gambar, API, atau koneksi internet eksternal. Gunakan tombol besar, teks mudah dibaca, serta tampilan responsif. Sediakan petunjuk, tombol mulai, satu soal per layar, skor, penjelasan jawaban, dan tombol ulang. Jawaban hanya dapat dinilai sekali per soal. Jangan gunakan timer sebagai syarat kelulusan.\n\nTuliskan soal dan kunci yang dapat diperiksa guru. Jika ada materi ambigu, jelaskan asumsi. Jangan menambahkan formulir pengumpulan data pribadi.\n\nKeluarkan kode HTML utuh dalam satu blok, lalu jelaskan cara menyimpan sebagai index.html dan membukanya di browser. Sebutkan bagian yang masih perlu diperiksa guru."}],"fields":[{"key":"mapel","label":"Mata pelajaran","type":"text","default":"Matematika","options":[]},{"key":"kelas","label":"Kelas","type":"text","default":"VIII SMP","options":[]},{"key":"topik","label":"Topik pembelajaran","type":"text","default":"Bilangan berpangkat","options":[]},{"key":"tema","label":"Tema permai