INSERT OR IGNORE INTO revisions(id,item_id,action,snapshot,created) VALUES('seed-prompt-kuis','prompt-kuis','Versi awal','{"id":"prompt-kuis","kind":"prompt","slug":"prompt-kuis-html","draft":"{\"summary\":\"Isi kelas, topik, tema, dan perangkat. Salin prompt hasil penyesuaian ke AI pilihanmu.\",\"category\":\"Pembelajaran\",\"cover\":\"\",\"video\":\"\",\"body\":\"Generator ini merangkai template di browser. Tidak mengirim isian ke layanan AI dan tidak membutuhkan kunci API. Setelah menyalin, tempel ke AI pilihanmu. Hasil kode tetap perlu diperiksa guru.\",\"version\":\"\",\"requirements\":\"\",\"readiness\":\"\",\"license\":\"\",\"links\":{\"download\":\"\",\"demo\":\"\",\"source\":\"\",\"issues\":\"\",\"guide\":\"\"},\"steps\":[{\"title\":\"Prompt dasar\",\"text\":\"Gunakan langsung atau sesuaikan melalui formulir di bawah.\",\"prompt\":\"Buat game kuis pembelajaran {{mapel}} untuk kelas {{kelas}}, topik {{topik}}, dengan tema {{tema}}. Buat {{jumlah}} soal dan optimalkan untuk {{perangkat}}.\\n\\nTujuan: siswa berlatih memahami materi melalui kuis dengan umpan balik yang jelas.\\n\\nHasilkan satu file HTML lengkap yang berisi CSS dan JavaScript di dalamnya. Tanpa pustaka, font, gambar, API, atau koneksi internet eksternal. Gunakan tombol besar, teks mudah dibaca, serta tampilan responsif. Sediakan petunjuk, tombol mulai, satu soal per layar, skor, penjelasan jawaban, dan tombol ulang. Jawaban hanya dapat dinilai sekali per soal. Jangan gunakan timer sebagai syarat kelulusan.\\n\\nTuliskan soal dan kunci yang dapat diperiksa guru. Jika ada materi ambigu, jelaskan asumsi. Jangan menambahkan formulir pengumpulan data pribadi.\\n\\nKeluarkan kode HTML utuh dalam satu blok, lalu jelaskan cara menyimpan sebagai index.html dan membukanya di browser. Sebutkan bagian yang masih perlu diperiksa guru.\"}],\"fields\":[{\"key\":\"mapel\",\"label\":\"Mata pelajaran\",\"type\":\"text\",\"default\":\"Matematika\",\"options\":[]},{\"key\":\"kelas\",\"label\":\"Kelas\",\"type\":\